T = int(input())
for iw in range(T):
	(n, m) = map(int, input().split())
	ans = 0
	X = [-1] * (n + 1)
	for i in range(m):
		(x, y) = map(int, input().split())
		if x != y:
			ans += 1
			X[x] = y
	for i in range(1, n + 1):
		if X[i] > 0:
			t = i
			while X[i] > 0:
				x = X[i]
				X[i] = 0
				i = x
				if i == t:
					ans += 1
					break
	print(ans)
